def max_sum_increasing_subseq(arr, n, i, k):
    dp = [0] * n
    for idx in range(n):
        current_val = arr[idx]
        max_prev = 0
        for prev in range(idx):
            if arr[prev] < current_val:
                if dp[prev] > max_prev:
                    max_prev = dp[prev]
        dp[idx] = current_val + max_prev

    max_prefix_sum = -float('inf')
    found = False
    for j in range(i + 1):
        if arr[j] < arr[k]:
            found = True
            if dp[j] > max_prefix_sum:
                max_prefix_sum = dp[j]

    return max_prefix_sum + arr[k] if found else arr[k]

def max_sum_increasing_subseq(arr, n, i, k):
    # We need to get max sum in prefix [0...i], increasing, then add arr[k] > last element of that subsequence
    if k <= i or i >= n or k >= n:
        return 0

    # Calculate max sum of increasing subsequence ending at each index in [0...i]
    dp = [arr[j] for j in range(i+1)]
    for j in range(1, i+1):
        for m in range(j):
            if arr[j] > arr[m] and dp[j] < dp[m] + arr[j]:
                dp[j] = dp[m] + arr[j]

    # Ensure increasing to arr[k], which means last element < arr[k]
    result = 0
    for j in range(i+1):
        if arr[j] < arr[k]:
            result = max(result, dp[j])

    if result == 0:
        return 0
    return result + arr[k]

