def magic_square_test(matrix):
    if not matrix:
        return False
    n = len(matrix)
    if any(len(row) != n for row in matrix):
        return False
    target_sum = sum(matrix[0])
    for row in matrix:
        if sum(row) != target_sum:
            return False
    for c in range(n):
        if sum(matrix[r][c] for r in range(n)) != target_sum:
            return False
    if sum(matrix[i][i] for i in range(n)) != target_sum:
        return False
    if sum(matrix[i][n-1-i] for i in range(n)) != target_sum:
        return False
    flat = [num for row in matrix for num in row]
    if sorted(flat) != list(range(1, n * n + 1)):
        return False
    return True

def magic_square_test(matrix):
    n = len(matrix)
    # Check for empty matrix or non-square matrix
    if n == 0 or any(len(row) != n for row in matrix):
        return False

    # The sum that every row, col, and diagonal should have
    target = sum(matrix[0])

    # Check each row
    for row in matrix:
        if sum(row) != target:
            return False

    # Check each column
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != target:
            return False

    # Check main diagonal
    if sum(matrix[i][i] for i in range(n)) != target:
        return False

    # Check anti-diagonal
    if sum(matrix[i][n - 1 - i] for i in range(n)) != target:
        return False

    return True

def eulerian_num(n, m):
    if m < 0 or m >= n:
        return 0
    if n == 0:
        return 1 if m == 0 else 0
    dp = [[0] * n for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(i):
            val = (j + 1) * dp[i - 1][j]
            if j > 0:
                val += (i - j) * dp[i - 1][j - 1]
            dp[i][j] = val
    return dp[n][m]

assert eulerian_num(3, 1) == 4

def eulerian_num(n, m):
    if n == 0:
        return int(m == 0)
    if m < 0 or m >= n:
        return 0
    return (n - m) * eulerian_num(n - 1, m - 1) + (m + 1) * eulerian_num(n - 1, m)

